<script>function todoForm(){return {subjectType:'{{ old('subject_type','lead') }}',subjectId:'{{ old('subject_id') }}',taskWith:'{{ old('task_with') }}',subjects:[],init(){this.loadSubjects()},async loadSubjects(clear=false){if(clear){this.subjectId='';this.taskWith=''}this.subjects=await (await fetch('{{ route('todos.subjects') }}?type='+this.subjectType)).json()},setTaskWith(){this.taskWith=this.subjects.find(x=>String(x.id)===String(this.subjectId))?.label||''}}}</script></x-app-layout>
